fn hermeline(off: f64, scl: f64) -> Vec<f64> {
    // If `scl` is exactly zero (including +0.0 or -0.0), we normalize to +0.0.
    // Otherwise we return `scl` unchanged.
    let second = if scl == 0.0 { 0.0 } else { scl };
    vec![off, second]
}

